```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int to;
    int next;
} Edge;

int head[200005];
Edge edges[800005];
int edge_cnt = 0;

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

int visited[200005];
int comp_nodes[200005];
int deg[200005];
int dist[200005];
int queue[200005];

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
        deg[i] = 0;
        visited[i] = 0;
    }

    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
        add_edge(v, u);
        deg[u]++;
        deg[v]++;
    }

    for (int i = 1; i <= n; i++) {
        if (!visited[i]) {
            int q_head = 0, q_tail = 0;
            queue[q_tail++] = i;
            visited[i] = 1;

            int comp_size = 0;
            long long edge_sum = 0;

            while (q_head < q_tail) {
                int u = queue[q_head++];
                comp_nodes[comp_size++] = u;
                edge_sum += deg[u];

                for (int e = head[u]; e != -1; e = edges[e].next) {
                    int v = edges[e].to;
                    if (!visited[v]) {
                        visited[v] = 1;
                        queue[q_tail++] = v;
                    }
                }
            }

            long long edges_in_comp = edge_sum / 2;
            long long max_edges = (long long)comp_size * (comp_size - 1) / 2;

            if (edges_in_comp < max_edges) {
                int start_node = -1;
                for (int j = 0; j < comp_size; j++) {
                    int u = comp_nodes[j];
                    if (deg[u] < comp_size - 1) {
                        start_node = u;
                        break;
                    }
                }

                for (int j = 0; j < comp_size; j++) {
                    dist[comp_nodes[j]] = -1;
                }

                q_head = 0;
                q_tail = 0;
                queue[q_tail++] = start_node;
                dist[start_node] = 0;

                while (q_head < q_tail) {
                    int u = queue[q_head++];
                    if (dist[u] == 2) {
                        printf("%d %d\n", start_node, u);
                        return 0;
                    }

                    for (int e = head[u]; e != -1; e = edges[e].next) {
                        int v = edges[e].to;
                        if (dist[v] == -1) {
                            dist[v] = dist[u] + 1;
                            queue[q_tail++] = v;
                        }
                    }
                }
            }
        }
    }

    printf("-1\n");
    return 0;
}
```

